// WHAT A BROWSER ACTUALLY DOES WITH A PUBLISHED SITE.
//
// WHAT THIS IS, precisely, because the distinction matters:
//
//   IT IS   a real Chromium, parsing the real bytes this app's real
//           pipeline produces, served at the real path shape a published
//           site is served at (/s/<subdomain> and /s/<subdomain>/<page>).
//           The nav is CLICKED and the resulting URL is read off the
//           browser. The <head> is read out of the DOM, not out of a
//           regex over a string.
//
//   IT IS NOT  a site generated by the model, and it is NOT the
//           production deployment. No ANTHROPIC_API_KEY is available in
//           this environment, so no site has been generated, published
//           or crawled. Nothing here proves what the MODEL writes — only
//           what happens to a document once it has been written.
//
// It exists because the navigation bug it checks was invisible to every
// string-level test in the repo: the pages were generated, stored in
// four tables and served at their own URLs, and every link to them had
// been rewritten to "#". A test that reads hrefs out of a string cannot
// tell you that a person clicking "About" lands on the about page. This
// one clicks it.
//
// Run: node scripts/tests/published-site-seo.prodtest.mjs
import { createServer } from "node:http";
import { chromium } from "playwright";
import { loadTs } from "./load-ts.mjs";

let pass = 0;
const failures = [];
const ok = (name, cond, detail) => {
  if (cond) { pass++; console.log(`  PASS  ${name}`); }
  else { failures.push(name); console.log(`  FAIL  ${name}${detail !== undefined ? "\n        " + detail : ""}`); }
};

const multi = await loadTs("src/lib/website-multipage.ts");
const linkSafety = await loadTs("src/lib/website-link-safety.ts");
const altText = await loadTs("src/lib/seo/alt-text.ts");
const seoHead = await loadTs("src/lib/seo/head.ts");
const nap = await loadTs("src/lib/seo/nap.ts");
const sitemapLib = await loadTs("src/lib/seo/sitemap.ts");

const SUBDOMAIN = "asteri";
const BASE_PATH = `/s/${SUBDOMAIN}`;

// ---------------------------------------------------------------------
// A model-shaped response: several complete documents behind page
// markers, with the nav the prompt asks for and the SEO hooks it asks
// for. Written here rather than generated, and that limit is the header.
// ---------------------------------------------------------------------
const NAV = `<nav>
<a href=".">Αρχική</a><a href="about">Το μαγαζί</a><a href="contact">Επικοινωνία</a>
</nav>`;
const HEADFOOT = (name, addr, tel) => `
<address data-seo-address="${addr}" data-seo-locality="Καλαμαριά">${addr}, Καλαμαριά</address>
<a href="tel:${tel}">${tel}</a><a href="mailto:hi@asteri.gr">hi@asteri.gr</a>
<p data-seo-hours>Mo-Fr 06:00-20:00</p><p data-seo-hours>Sa 07:00-15:00</p>`;

const page = (slug, label, title, desc, body) =>
  `<!--IONEXA:PAGE slug="${slug}" label="${label}"-->
<!DOCTYPE html><html lang="el"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title><meta name="description" content="${desc}">
<style>body{font-family:system-ui;margin:0;padding:24px}nav a{margin-right:12px}</style></head>
<body>${NAV}<h1 data-seo-name="Φούρνος Αστέρι" data-seo-type="Bakery">${title}</h1>
${body}${HEADFOOT("Φούρνος Αστέρι", "Κομνηνών 8", "+302310444555")}</body></html>`;

const RAW = [
  page("home", "Αρχική", "Φούρνος Αστέρι",
    "Παραδοσιακός φούρνος στην Καλαμαριά με προζύμι — ζυμώνουμε κάθε πρωί από τις πέντε.",
    `<p>Ζυμώνουμε με προζύμι κάθε πρωί από τις πέντε, στην ίδια γωνία της Καλαμαριάς.</p>
     <img src="https://images.unsplash.com/photo-a" data-image-query="sourdough loaves cooling on a rack">
     <img src="https://images.unsplash.com/photo-b">`),
  page("about", "Το μαγαζί", "Το μαγαζί — Φούρνος Αστέρι",
    "Τριάντα χρόνια στην ίδια γωνία της Καλαμαριάς, με τον ίδιο ξυλόφουρνο και το ίδιο προζύμι.",
    `<p>Τριάντα χρόνια στην ίδια γωνία, με τον ίδιο ξυλόφουρνο και το ίδιο προζύμι από την αρχή.</p>`),
  page("contact", "Επικοινωνία", "Επικοινωνία — Φούρνος Αστέρι",
    "Πού θα μας βρείτε στην Καλαμαριά, τι ώρα ανοίγουμε και πώς να μας τηλεφωνήσετε.",
    `<p>Είμαστε στην Κομνηνών, λίγο πριν την πλατεία — τηλεφωνήστε μας για παραγγελίες.</p>
     <details><summary>Έχετε χωρίς γλουτένη;</summary><p>Κάθε Πέμπτη.</p></details>`),
].join("\n");

// ---------------------------------------------------------------------
// THE REAL PIPELINE, in the real order, at both moments.
// ---------------------------------------------------------------------
const split = multi.splitGeneratedPages(RAW);
if (split.dropped.length > 0) {
  console.log(`  FAIL  the fixture itself did not survive the splitter\n        ${split.dropped.join(" | ")}`);
  process.exit(1);
}
const slugs = split.pages.map((p) => p.slug);

// Generation: links stay relative, head and alt are established.
const generated = [split.home, ...split.pages.map((p) => p.html)].map((doc) => {
  const safe = linkSafety.makeGeneratedLinksSafe(doc, { pageSlugs: slugs }).html;
  return seoHead.enforceSeoHead(altText.enforceImageAltText(safe).html).html;
});

// Publish: the address is known, so the links resolve and the
// URL-dependent tags are written.
const SITE_URL = `http://127.0.0.1:PORT${BASE_PATH}`;
function publishAll(origin) {
  const siteUrl = `${origin}${BASE_PATH}`;
  const documents = generated.map((doc) =>
    linkSafety.makeGeneratedLinksSafe(doc, { pageSlugs: slugs, basePath: BASE_PATH }).html
  );
  const report = nap.siteNap([
    { label: "home", html: documents[0] },
    ...split.pages.map((p, i) => ({ label: p.slug, html: documents[i + 1] })),
  ]);
  const homeCrumb = { name: report.nap.name ?? SUBDOMAIN, url: siteUrl };
  const seoFor = (doc, pageUrl, crumbs) =>
    seoHead.enforceSeoHead(altText.enforceImageAltText(doc).html, {
      canonicalUrl: pageUrl,
      siteUrl,
      siteName: report.nap.name ?? null,
      breadcrumb: crumbs,
      nap: report.nap,
    }).html;
  const out = new Map();
  out.set(BASE_PATH, seoFor(documents[0], siteUrl, []));
  split.pages.forEach((p, i) => {
    const url = `${siteUrl}/${p.slug}`;
    out.set(`${BASE_PATH}/${p.slug}`, seoFor(documents[i + 1], url, [homeCrumb, { name: p.label, url }]));
  });
  return { pages: out, report, siteUrl };
}

// ---------------------------------------------------------------------
const server = createServer((req, res) => {
  const path = (req.url ?? "/").split("?")[0].replace(/\/+$/, "") || "/";
  if (path === `${BASE_PATH}/sitemap.xml`) {
    res.writeHead(200, { "Content-Type": "application/xml; charset=utf-8" });
    res.end(SITEMAP_XML);
    return;
  }
  const body = SERVED.get(path);
  if (!body) {
    res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
    res.end("<!doctype html><title>Site not found</title>");
    return;
  }
  res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
  res.end(body);
});
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const PORT = server.address().port;
const ORIGIN = `http://127.0.0.1:${PORT}`;
const published = publishAll(ORIGIN);
const SERVED = published.pages;
const SITEMAP_XML = sitemapLib.buildSitemapXml(
  sitemapLib.siteSitemapEntries(published.siteUrl, slugs, new Date("2026-08-22T10:00:00Z"))
);
void SITE_URL;

const proxyServer = process.env.HTTPS_PROXY || process.env.https_proxy || "";
const browser = await chromium.launch({
  executablePath: process.env.CHROMIUM_PATH || "/opt/pw-browsers/chromium",
  args: ["--no-sandbox", "--disable-dev-shm-usage", "--ssl-version-max=tls1.2"],
  ...(proxyServer ? { proxy: { server: proxyServer, bypass: "127.0.0.1,localhost" } } : {}),
});

try {
  const page = await browser.newPage();

  console.log("== 1. THE NAV IS CLICKED, and the browser goes there ==");
  // The bug: every one of these was href="#". Reading the href is not
  // the same as going there — a relative href on the HOME page resolves
  // one directory up and lands off the site, which is exactly the case a
  // string test cannot see.
  await page.goto(`${ORIGIN}${BASE_PATH}`, { waitUntil: "domcontentloaded" });
  ok("the home page loads", page.url() === `${ORIGIN}${BASE_PATH}`, page.url());

  for (const [label, expected] of [["Το μαγαζί", `${BASE_PATH}/about`], ["Επικοινωνία", `${BASE_PATH}/contact`]]) {
    await page.goto(`${ORIGIN}${BASE_PATH}`, { waitUntil: "domcontentloaded" });
    await page.click(`nav >> text=${label}`);
    await page.waitForLoadState("domcontentloaded");
    const landed = new URL(page.url()).pathname;
    ok(`clicking "${label}" from the HOME page lands on ${expected}`, landed === expected, landed);
    // And the page that answered is the right one, not a 404 body.
    const heading = await page.textContent("h1");
    ok(`...on a real page, not the not-found page`, Boolean(heading) && !/not available/i.test(heading ?? ""), heading);
  }

  // From a SUB-page, where a relative nav happens to work — so a fix that
  // only ever tested here would look complete.
  await page.goto(`${ORIGIN}${BASE_PATH}/about`, { waitUntil: "domcontentloaded" });
  await page.click("nav >> text=Επικοινωνία");
  await page.waitForLoadState("domcontentloaded");
  ok("clicking through from a SUB-page works too",
    new URL(page.url()).pathname === `${BASE_PATH}/contact`, new URL(page.url()).pathname);

  await page.goto(`${ORIGIN}${BASE_PATH}/about`, { waitUntil: "domcontentloaded" });
  await page.click("nav >> text=Αρχική");
  await page.waitForLoadState("domcontentloaded");
  ok("and Home goes back to the site root", new URL(page.url()).pathname === BASE_PATH, new URL(page.url()).pathname);

  // NO LINK LEAVES THE SITE BY ACCIDENT. The original report was a nav
  // that landed visitors on somebody else's sign-in page.
  for (const path of [BASE_PATH, `${BASE_PATH}/about`, `${BASE_PATH}/contact`]) {
    await page.goto(`${ORIGIN}${path}`, { waitUntil: "domcontentloaded" });
    const offSite = await page.$$eval("a[href]", (as, base) =>
      as
        .map((a) => a.href)
        .filter((h) => h.startsWith("http"))
        .filter((h) => !h.startsWith(base))
        .filter((h) => !/^https?:\/\/(www\.)?(unsplash|maps\.google|facebook|instagram)\./.test(h)),
      `${ORIGIN}${BASE_PATH}`
    );
    ok(`${path}: no link resolves off the site`, offSite.length === 0, offSite.join(" | "));
  }

  console.log("\n== 2. the <head> a crawler reads, out of the DOM ==");
  for (const [path, expectTitle] of [
    [BASE_PATH, "Φούρνος Αστέρι"],
    [`${BASE_PATH}/about`, "Το μαγαζί — Φούρνος Αστέρι"],
    [`${BASE_PATH}/contact`, "Επικοινωνία — Φούρνος Αστέρι"],
  ]) {
    await page.goto(`${ORIGIN}${path}`, { waitUntil: "domcontentloaded" });
    const head = await page.evaluate(() => ({
      title: document.title,
      description: document.querySelector('meta[name="description"]')?.getAttribute("content") ?? null,
      canonical: document.querySelector('link[rel="canonical"]')?.getAttribute("href") ?? null,
      ogUrl: document.querySelector('meta[property="og:url"]')?.getAttribute("content") ?? null,
      ogTitle: document.querySelector('meta[property="og:title"]')?.getAttribute("content") ?? null,
      ogImage: document.querySelector('meta[property="og:image"]')?.getAttribute("content") ?? null,
      twitterCard: document.querySelector('meta[name="twitter:card"]')?.getAttribute("content") ?? null,
      lang: document.documentElement.lang,
      titles: document.querySelectorAll("title").length,
      descriptions: document.querySelectorAll('meta[name="description"]').length,
      canonicals: document.querySelectorAll('link[rel="canonical"]').length,
      ld: [...document.querySelectorAll('script[type="application/ld+json"]')].map((s) => s.textContent ?? ""),
      images: [...document.querySelectorAll("img")].map((i) => ({ src: i.getAttribute("src"), alt: i.getAttribute("alt") })),
      h1s: document.querySelectorAll("h1").length,
    }));

    ok(`${path}: the title is this page's own`, head.title === expectTitle, head.title);
    ok(`${path}: it has a description`, (head.description ?? "").length >= 50, head.description);
    ok(`${path}: the canonical is THIS page`, head.canonical === `${ORIGIN}${path}`, head.canonical);
    ok(`${path}: og:url matches the canonical`, head.ogUrl === head.canonical, head.ogUrl);
    ok(`${path}: og:title matches the title`, head.ogTitle === head.title, head.ogTitle);
    ok(`${path}: the document declares its language`, head.lang === "el", head.lang);
    ok(`${path}: exactly one title`, head.titles === 1, String(head.titles));
    ok(`${path}: exactly one description`, head.descriptions === 1, String(head.descriptions));
    ok(`${path}: exactly one canonical`, head.canonicals === 1, String(head.canonicals));
    ok(`${path}: exactly one <h1>`, head.h1s === 1, String(head.h1s));
    ok(`${path}: a twitter card is declared`, Boolean(head.twitterCard), head.twitterCard);
    ok(`${path}: EVERY image has an alt attribute`,
      head.images.every((i) => typeof i.alt === "string"),
      JSON.stringify(head.images));
    ok(`${path}: and no alt is a filler word`,
      !head.images.some((i) => /^(image|photo|picture)$/i.test(i.alt ?? "")),
      JSON.stringify(head.images.map((i) => i.alt)));

    // THE STRUCTURED DATA, PARSED BY THE BROWSER'S OWN JSON.
    ok(`${path}: exactly one JSON-LD block`, head.ld.length === 1, String(head.ld.length));
    let parsed = null;
    try { parsed = JSON.parse(head.ld[0]); } catch (e) { parsed = null; }
    ok(`${path}: the JSON-LD parses`, parsed !== null, head.ld[0]?.slice(0, 120));
    const nodes = parsed ? (parsed["@graph"] ?? [parsed]) : [];
    const types = nodes.map((n) => n["@type"]);
    ok(`${path}: it declares the schema.org context`, parsed?.["@context"] === "https://schema.org");
    ok(`${path}: the business is described as a Bakery`, types.includes("Bakery"), types.join(","));
    const biz = nodes.find((n) => n["@type"] === "Bakery");
    ok(`${path}: with the SAME address as every other page`,
      biz?.address?.streetAddress === "Κομνηνών 8", JSON.stringify(biz?.address));
    ok(`${path}: and the SAME phone`, biz?.telephone === "+302310444555", biz?.telephone);
    ok(`${path}: and both opening-hours lines`,
      biz?.openingHours?.join("|") === "Mo-Fr 06:00-20:00|Sa 07:00-15:00", JSON.stringify(biz?.openingHours));
    // NO SCRIPT ESCAPED ITS BLOCK.
    const scriptCount = await page.evaluate(() => document.querySelectorAll("script").length);
    ok(`${path}: the only script on the page is the JSON-LD`, scriptCount === 1, String(scriptCount));
  }

  console.log("\n== 3. the pages the sitemap advertises actually answer ==");
  const xml = await (await fetch(`${ORIGIN}${BASE_PATH}/sitemap.xml`)).text();
  const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
  ok("the sitemap lists the home page and every page", locs.length === 1 + slugs.length, locs.join(" "));
  for (const loc of locs) {
    const res = await fetch(loc);
    ok(`${new URL(loc).pathname} answers 200`, res.status === 200, String(res.status));
  }
  // AND IT IS WELL-FORMED XML, parsed by the browser rather than by me.
  const xmlOk = await page.evaluate(async (url) => {
    const text = await (await fetch(url)).text();
    const doc = new DOMParser().parseFromString(text, "application/xml");
    return {
      error: doc.querySelector("parsererror")?.textContent ?? null,
      urls: doc.getElementsByTagName("url").length,
      root: doc.documentElement.nodeName,
    };
  }, `${ORIGIN}${BASE_PATH}/sitemap.xml`);
  ok("the sitemap is well-formed XML", xmlOk.error === null, xmlOk.error?.slice(0, 160));
  ok("...with a <urlset> root", xmlOk.root === "urlset", xmlOk.root);
  ok("...and one <url> per page", xmlOk.urls === 1 + slugs.length, String(xmlOk.urls));

  console.log("\n== 4. the site speaks with ONE voice about itself ==");
  ok("the pipeline found no NAP disagreement in a consistent site",
    published.report.disagreements.length === 0, JSON.stringify(published.report.disagreements));
  ok("...and the name it settled on came off the page",
    published.report.nap.name === "Φούρνος Αστέρι", published.report.nap.name);
} finally {
  await browser.close();
  server.close();
}

console.log(`\n${pass} passed, ${failures.length} failed`);
if (failures.length) console.log("FAILED:\n  " + failures.join("\n  "));
process.exit(failures.length === 0 ? 0 : 1);
